package com.sirithree.shopops.admin.benchmark.v1.dataset.stage7b; import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test; import java.util.*;
class GovernanceScaleupNearDuplicateTest { @Test void everyCandidatePairHasModelReview() throws Exception { Map<String,Object>d=Stage7BGovernanceDatasetSupport.objectResource("/benchmark/v1/governance/scaleup/governance-near-duplicate-review.json"); @SuppressWarnings("unchecked") List<Map<String,Object>> a=(List<Map<String,Object>>)d.get("decisions"); assertThat(a).hasSize(((Number)d.get("candidateCount")).intValue()); assertThat(a).allSatisfy(x->assertThat(x.get("reviewStatus")).isEqualTo("MODEL_REVIEWED")); }}
